//                                         .with_req_grad(true);
//     auto shape = layer.weight.shape();
//     layer.weight = Tensor::randn<float>(shape, opts, seed, std);
//     if (layer.bias.is_valid()) {
//         layer.bias = Tensor::zeros(layer.bias.shape(), opts);
//         // layer.bias = Tensor::randn<float>(layer.bias.shape(), opts, seed,
//         std);
//     }
//     // std::cout << "WEIGHT: " << std::endl;
//     // layer.weight.display();
//     // std::cout << "BIAS: " << std::endl;
//     // layer.bias.display();
// }

class MLP : public dnn::DModule {
public:
  nn::LayerNorm ln;         // LayerNorm before MLP
  dnn::DColumnLinear fc_up; // Linear(n_embd, 4*n_embd)
  dnn::DRowLinear fc_down;  // Linear(4*n_embd, n_embd)
  dnn::DGeLU gelu;

  MLP(GPTConfig config, DeviceMesh &mesh, std::shared_ptr<ProcessGroupNCCL> &pg,
      DeviceIndex device, uint64_t seed = 1234)
      : ln(config.n_embd),
        // DColumnLinear: weight_data, use_bias, sd, seed, sync_input,
        // use_backward_hook MUST sync backward partial gradients! Set
        // use_backward_hook = true
        fc_up(mesh, pg, config.batch_size, config.context_length, config.n_embd,
              4 * config.n_embd, {}, true, 0.02f, seed, false, true),

        // DRowLinear: weight_data, use_bias, sd, seed, sync_output,
        // with_autograd Let's rely on manual sync for clarity.
        fc_down(mesh, pg, config.batch_size, config.context_length,
                4 * config.n_embd, config.n_embd, {}, true,
                0.02f * (1.0f /
                         std::sqrt(2.0f * static_cast<float>(config.n_layers))),
                seed, true, false)

  {
    // Move LayerNorm to device
    ln.to(device);

    register_module(ln);
    register_module(fc_up);
    register_module(fc_down);
  }

  using dnn::DModule::register_module;

  void register_module(nn::LayerNorm &m) {
    register_parameter(&m.weight);
    if (m.bias.is_valid())
      register_parameter(&m.bias);
  }

  // Forward: x [B, T, C] -> [B, T, C]
  DTensor forward(DTensor &x) {

    // Backward-only sync via Hook is now handled by fc_up
    // (use_backward_hook=true)

    // Pre-Norm: ln(x)
    DTensor h(x.get_device_mesh(), x.get_pg(), x.get_layout(),
              "h_intermediate");
    h.mutable_tensor() = ln.forward(x.mutable_tensor());

    // Up projection + GELU + Down projection
    h = fc_up.forward(h);
    h = gelu.forward(h);
    h = fc_down.forward(h);

    // We MUST sum the partial features across ranks BEFORE adding to the
    // residual.
    // h.sync();

    // Residual connection: x + MLP(x)
    h.mutable_tensor() = autograd::add(x.mutable_tensor(), h.mutable_tensor());
    return h;
  }

private:
  int64_t n_embd_;
};

// =============================================================================
// GPT Model (WITHOUT Weight Tying)
// =============================================================================

class GPT : public dnn::DModule {
public:
  GPTConfig config;
  DeviceMesh &mesh;
  std::shared_ptr<ProcessGroupNCCL> pg_ptr; // Store pg for forward layout
  autograd::DEmbeddingVParallelFused wte;        // Token embedding (fused kernel)
  Embedding wpe;                            // Position embedding
  dnn::DSequential mlps;
  nn::LayerNorm ln_f; // Final LayerNorm
  std::shared_ptr<dnn::DLMHead>
      lm_head; // Output projection [n_embd, vocab_size], bias=False
  // Tensor& W_out;
  Tensor pos;
  DTensor logits;
  Tensor cached_pos_; // Position indices cached on GPU
  // std::vector<float> weight_data = {};
  // Component timing (accumulated per step, reset after printing)
  double t_tok_emb = 0, t_pos_emb = 0, t_mlp = 0, t_ln_f = 0, t_lm_head = 0;
  CudaTimer timer_tok_emb, timer_pos_emb, timer_mlp, timer_ln_f, timer_lm_head;

  GPT(GPTConfig cfg, DeviceMesh &mesh, std::shared_ptr<ProcessGroupNCCL> &pg,
      DeviceIndex device, uint64_t seed = 1234)
      : config(cfg), mesh(mesh), pg_ptr(pg),
        wte(mesh, pg, cfg.vocab_size, cfg.n_embd, (float)0.02f, seed = 1234 , true),
        wpe(cfg.context_length, cfg.n_embd, device), ln_f(cfg.n_embd),
        lm_head() {

    ln_f.to(device);

    // Create MLP blocks and add to Sequential
    for (int i = 0; i < cfg.n_layers; ++i) {
      mlps.add(std::make_shared<MLP>(config, mesh, pg, device, 1234));
    }

    if (!config.weight_tying) {
      lm_head = std::make_shared<dnn::DLMHead>(mesh, pg, cfg.batch_size,
                                               cfg.n_embd, cfg.vocab_size, true,
                                               wte.weight.get());
      lm_head->to(device);
    } else {
      lm_head = std::make_shared<dnn::DLMHead>(
          mesh, pg, cfg.batch_size, cfg.context_length, cfg.n_embd,
          // cfg.vocab_size, config.weight_tying, wte.weight->mutable_tensor())
          // {
          cfg.vocab_size, config.weight_tying, wte.weight.get());
    }

    // Optimization: cache position tensor once (avoids re-creating + H2D
    // transfer every forward)

    Tensor pos_cpu(Shape{{1, cfg.context_length}},
                   TensorOptions().with_dtype(Dtype::Int64));
    int64_t *pos_data = pos_cpu.data<int64_t>();
    for (int64_t i = 0; i < cfg.context_length; ++i) {
      pos_data[i] = i;
    }
    cached_pos_ = pos_cpu.to(device);

    register_module(wte);
    register_module(wpe);
    register_module(mlps);
    register_module(ln_f);
    register_module(*lm_head.get());
  }

  // using dnn::DModule::register_module;
  // void register_module(nn::LayerNorm& m) {
  //     register_parameter(&m.weight);
  //     if(m.bias.is_valid()) register_parameter(&m.bias);
  // void register_module(Embedding& m) {
  //     register_parameter(&m.weight);
  // }

  using dnn::DModule::register_module;

  void register_module(Embedding &m) { register_parameter(&m.weight); }

  void register_module(nn::LayerNorm &m) {
    register_parameter(&m.weight);
    if (m.bias.is_valid())
      register_parameter(&m.bias);
  }

  void register_module(nn::Linear &m) {
    register_parameter(&m.weight);
    if (m.bias.is_valid())
      register_parameter(&m.bias);
  }

  void reset_timing() {
    t_tok_emb = t_pos_emb = t_mlp = t_ln_f = t_lm_head = 0;
  }

  void print_timing(int rank) {
    if (rank == 0) {
      std::cout << "  [LAYER] tok_emb: " << std::fixed << std::setprecision(1)
                << (t_tok_emb * 1000.0) << "ms"
                << " | pos_emb: " << (t_pos_emb * 1000.0) << "ms"
                << " | mlps: " << (t_mlp * 1000.0) << "ms"
                << " | ln_f: " << (t_ln_f * 1000.0) << "ms"
                << " | lm_head: " << (t_lm_head * 1000.0) << "ms" << std::endl;
    }
  }

  DTensor forward(DTensor &idx) {
    auto shape = idx.get_layout().get_global_shape();
    int64_t B = shape[0];
    int64_t T = shape[1];

    // --- Token Embedding ---
    timer_tok_emb.start_timer();
    Tensor tok_emb = wte.forward(idx.mutable_tensor()); // [B, T, C]

    t_tok_emb += timer_tok_emb.get_elapsed_seconds();

    // --- Position Embedding ---
    timer_pos_emb.start_timer();
    Tensor pos_flat =
        autograd::reshape(cached_pos_, Shape({{config.context_length}}));
    Tensor pos_sliced = pos_flat.slice(0, T);
    Tensor pos_indices = autograd::reshape(pos_sliced, Shape({{1, T}}));

    Tensor pos_emb = wpe.forward(pos_indices); // [1, T, C] - broadcasts

    t_pos_emb += timer_pos_emb.get_elapsed_seconds();

    // Add embeddings
    Layout input_layout(mesh, {B, T, config.n_embd});
    DTensor current_x(mesh, pg_ptr, input_layout, "x_combined");
    current_x.mutable_tensor() = autograd::add(tok_emb, pos_emb);

    current_x.register_backward_node(); // SUM

    // --- MLP Blocks ---
    timer_mlp.start_timer();
    current_x = mlps.forward(current_x);

    t_mlp += timer_mlp.get_elapsed_seconds();

    // --- Final LayerNorm ---
    timer_ln_f.start_timer();
    current_x.mutable_tensor() = ln_f.forward(current_x.mutable_tensor());

    t_ln_f += timer_ln_f.get_elapsed_seconds();

    // --- LM Head ---
    // DLMHead is ColumnParallel, its backward produces a partial gradient for
    // current_x. We must all-reduce this partial gradient before it flows back
    // to ln_f.
    current_x.register_backward_node();

    timer_lm_head.start_timer();
    logits = lm_head->forward(current_x);

    t_lm_head += timer_lm_head.get_elapsed_seconds();
    // std::cout << "Here:" << std::endl;

    return logits;
  }
};

// =============================================================================
// Learning Rate Scheduler
// =============================================================================

float get_lr(int step, float max_lr, float min_lr, int warmup_steps,
             int max_steps) {
  if (step < warmup_steps) {
    return max_lr * static_cast<float>(step + 1) /
           static_cast<float>(warmup_steps);
  }
  if (step > max_steps) {
    return min_lr;
  }
  float decay_ratio = static_cast<float>(step - warmup_steps) /
                      static_cast<float>(max_steps - warmup_steps);
  float coeff = 0.5f * (1.0f + std::cos(M_PI * decay_ratio));
  return min_lr + coeff * (max_lr - min_lr);
}

// =============================================================================
// Tiktoken Decoder (via Python popen)
// =============================================================================

std::string decode_tokens_tiktoken(const std::vector<int64_t> &tokens) {
  std::string cmd = "python3 -c \"import tiktoken; enc = "
                    "tiktoken.get_encoding('gpt2'); print(enc.decode([";
  for (size_t i = 0; i < tokens.size(); ++i) {
    if (i > 0)
      cmd += ",";
    cmd += std::to_string(tokens[i]);
  }
  cmd += "]))\" 2>/dev/null";

  std::string result;
  FILE *pipe = popen(cmd.c_str(), "r");
  if (pipe) {
    char buffer[512];
    while (fgets(buffer, sizeof(buffer), pipe) != nullptr) {
      result += buffer;
    }
    pclose(pipe);
  }
  if (!result.empty() && result.back() == '\n')
    result.pop_back();
  return result;
}

