              pg->broadcast(ix.data<int64_t>(), ix.data<int64_t>(), ix.numel(),
                            OwnTensor::Dtype::Int64, 0, true);
            }

            Tensor topk_indices_2d =
                OwnTensor::autograd::reshape(topk_indices, Shape({{Bg, 50}}));
            Tensor next_token = OwnTensor::gather(topk_indices_2d, 1, ix);

