            // Append generated tokens to config file

            std::ofstream config_append(config_filename, std::ios::app);
            config_append << "\n--- Generated Tokens at Step " << step
                          << " ---\n";

            for (int i = 0; i < Bg; ++i) {
              // Collect token IDs into a vector and a printable string
              std::vector<int64_t> sample_tokens;
              std::string token_str;
              for (int j = 0; j < Tg; ++j) {
                sample_tokens.push_back(data[i * Tg + j]);
                if (j > 0)
                  token_str += " ";
                token_str += std::to_string(data[i * Tg + j]);
              }

              // Print raw IDs
              std::cout << "Sample " << i << " [IDs]: " << token_str
                        << std::endl;

              // Decode via tiktoken popen
              std::string decoded = decode_tokens_tiktoken(sample_tokens);
              std::cout << "Sample " << i << " [Text]: " << decoded
                        << std::endl;

              // Log both to config file
              config_append << "Sample " << i << " [IDs]: " << token_str
                            << "\n";
              config_append << "Sample " << i << " [Text]: " << decoded << "\n";
            }
            config_append.close();
          }
        }

        // Training step with component timing
        double time_data = 0, time_forward = 0, time_loss = 0,
        time_backward = 0, time_allreduce = 0, time_clip = 0,
        time_optim = 0;


        optimizer.zero_grad();
        float loss_accum = 0.0f;

        // Optimized: Accumulate loss on GPU to avoid CPU syncs
        Tensor loss_accum_gpu =
            Tensor::zeros(Shape{{1}}, TensorOptions().with_device(device));

        static Tensor grad_scale =
            Tensor::full(Shape{{1}}, TensorOptions().with_device(device),
                         1.0f / static_cast<float>(grad_accum_steps));

        for (int micro_step = 0; micro_step < grad_accum_steps; ++micro_step) {

          // --- Data Loading ---
          timer_data.start_timer();
          Batch batch = train_loader.next_batch();
          x.mutable_tensor() = batch.input.to(device).as_type(Dtype::Int64);
          Tensor y = batch.target.to(device).as_type(Dtype::Int64);

          time_data += timer_data.get_elapsed_seconds();

          // --- Forward Pass ---
          timer_fwd.start_timer();
          DTensor logits = model.forward(x);

          time_forward += timer_fwd.get_elapsed_seconds();

          // --- Loss Computation ---
          timer_loss.start_timer();
          Tensor loss = autograd::vocab_parallel_cross_entropy_v2(logits, y);

          loss_accum_gpu = loss_accum_gpu + loss.detach();

          time_loss += timer_loss.get_elapsed_seconds();

          // --- Backward Pass ---
          timer_bwd.start_timer();
          loss.backward(&grad_scale);
          time_backward += timer_bwd.get_elapsed_seconds();
        }

        if (!model.config.weight_tying &&
            model.lm_head->weight->mutable_tensor().has_grad()) {
          Tensor lm_grad_T = model.lm_head->weight->mutable_tensor()
                                 .grad_view()
                                 .transpose(0, 1)
                                 .contiguous();
          Tensor wte_grad =
              model.wte.weight->mutable_tensor().grad_view(); // [vocab, embd]
          // In-place accumulate: wte_grad += lm_grad_transposed
          wte_grad += lm_grad_T;
        }

        // // TEMP DEBUGGING: Print parameter gradients to check cross-rank sync
        // if ((grad_accum_steps + 1) % 1 == 0) {
        //   for (int r = 0; r < world_size; ++r) {
        //     if (rank == r) {
        //       std::cout << "\n=== DEBUG: Parameter Gradients at Step " << step
        //                 << " [Rank " << rank << "] ===" << std::endl;
        //       for (auto *p : params) {
        //         if (p->mutable_tensor().has_grad()) {
        //           std::cout << "\nParam: " << p->name()
        //                     << " | size: " << p->mutable_tensor().numel()
        //                     << std::endl;
        //           try {
        //             // p->mutable_tensor().grad_view().display();
        //             p->mutable_tensor().display();
        //           } catch (const std::exception &e) {
        //             std::cout << "  Error displaying grad: " << e.what()
        //                       << std::endl;
        //           }
        //         } else {
        //           std::cout << "Param: " << p->name() << " | NO GRADIENT"
        //                     << std::endl;
        //         }
        //       }
        //       std::cout << "=================================================\n"
        //                 << std::endl;
        //     }
        //     MPI_Barrier(MPI_COMM_WORLD);
        //   }
        // }

        // Transfer accumulated loss to CPU once per step
        Tensor loss_cpu = loss_accum_gpu.to_cpu();
        loss_accum =
            loss_cpu.data<float>()[0] / static_cast<float>(grad_accum_steps);

        // NaN detection - early exit if training goes unstable
        if (std::isnan(loss_accum) || std::isinf(loss_accum)) {
          std::cerr << "ERROR: NaN/Inf detected in loss at step " << step
                    << std::endl;
          log_file.close();
          return 1;
        }

        // --- Gradient Clipping ---
        timer_clip.start_timer();
        float norm = nn::clip_grad_norm_(tensor_params, 1.0f);

        time_clip = timer_clip.get_elapsed_seconds();

        // Update learning rate
        float lr = get_lr(step, max_lr, min_lr, warmup_steps, max_steps);
        optimizer.set_lr(lr);

        // --- Optimizer Step ---
        timer_optim.start_timer();
        optimizer.step();

        time_optim = timer_optim.get_elapsed_seconds();

        double dt = timer_step.get_elapsed_seconds();

          // Compute throughput
          int64_t tokens_processed =
              static_cast<int64_t>(B) * T * grad_accum_steps;
          double tokens_per_sec = static_cast<double>(tokens_processed) / dt;
          long long total_sec = static_cast<long long>((max_steps - step) * dt);

          int h = total_sec / 3600;
          int m = (total_sec % 3600) / 60;
          int s = total_sec % 60;

        // Print training info
        if (rank == 0) {
          std::cout << "step " << std::setw(5) << step
                    << " | loss: " << std::fixed << std::setprecision(6)
                    << loss_accum << " | lr " << std::scientific
                    << std::setprecision(4) << lr << " | norm: " << std::fixed
                    << std::setprecision(4) << norm << " | dt: " << std::fixed
                    << std::setprecision(2) << (dt * 1000.0) << "ms"
                    << " | tok/sec: " << std::fixed << std::setprecision(2)
                    << tokens_per_sec
                    << " |       Time Left: " << std::setfill('0')
                    << std::setprecision(2) << h << " hrs : " << m << " mins "
                    << std::endl;

          // Component timing breakdown (in ms)
          std::cout
              << "  [TIMING] data: " << std::fixed << std::setprecision(1)
              << (time_data * 1000.0) << "ms"
              << " | fwd: " << (time_forward * 1000.0) << "ms"
              << " | loss: " << (time_loss * 1000.0) << "ms"
              << " | bwd: " << (time_backward * 1000.0) << "ms"
              << " | clip: " << (time_clip * 1000.0) << "ms"
              << " | optim: " << (time_optim * 1000.0)
              << "ms"
              //   << " | gradients allreduce: " << std::fixed <<
              //   std::setprecision(1) << (time_allreduce * 1000.0) << "ms"
              << std::endl;

          // Layer-level timing breakdown
          model.print_timing(rank);

          // Log metrics to CSV
          log_file << step << "," << loss_accum << "," << val_loss_accum_log
                   << "," << lr << "," << norm << "," << (dt * 1000.0) << ","
                   << tokens_per_sec << "," << (time_data * 1000.0) << ","
                   << (time_forward * 1000.0) << "," << (time_loss * 1000.0)
                   << "," << (time_backward * 1000.0) << ","
                   << (time_clip * 1000.0) << "," << (time_optim * 1000.0)
                   << "," << (model.t_tok_emb * 1000.0) << ","
                   << (model.t_pos_emb * 1000.0) << ","
                   << (model.t_mlp * 1000.0) << "," << (model.t_ln_f * 1000.0)
                   << "," << (model.t_lm_head * 1000.0) << "\n";

          log_file.flush();
          model.reset_timing();
        }
        val_loss_accum_log = -1.0f; // Reset for next iteration
      } catch (const std::exception &e) {
        std::cerr << "EXCEPTION IN RANK " << rank << " AT STEP " << step << ": "
                  << e.what() << std::endl;
        std::exit(1);
      }
    }
    if (rank == 0) {
      log_file.close();
      std::cout << "\nTraining log saved to: " << log_filename << std::endl;

      std::cout << "\n=== Training Complete ===" << std::endl;
    }

    MPI_Finalize();
    return 0;

  } catch (const std::exception &e) {
    std::cerr << "ERROR: " << e.what() << __LINE__ << std::endl;
    MPI_Finalize();
    return 1;
  }
}

