          log_file.flush();
        }

        val_loss_log = -1.0f;

      } catch (const std::exception &e) {
        std::cerr << "EXCEPTION RANK " << rank << " STEP " << step << ": "
                  << e.what() << "\n";
        std::exit(1);
      }
    }

    if (rank == 0) {
      log_file.close();
      std::cout << "\nTraining log saved to: " << log_filename << "\n";
      std::cout << "\n=== Context Parallel Training Complete ===\n";
    }

  } catch (const std::exception &e) {
    std::cerr << "ERROR: " << e.what() << "\n";
    MPI_Finalize();
    return 1;
  }

  MPI_Finalize();
  return 0;
}

