// NVTX wrapper (TensorLib already includes nvToolsExt.h internally)
class EmitNVTX {
public:
  EmitNVTX(const char *name) { nvtxRangePushA(name); }
  ~EmitNVTX() { nvtxRangePop(); }
};
#define emit_nvtx(name) EmitNVTX nvtx_tmp_##__LINE__(name)
